/// Write a function to find the maximum sum of increasing subsequence from prefix until ith index and also including a given kth element which is after i, i.e., k > i .
fn max_sum_increasing_subseq(a: Vec<isize>, n: isize, index: isize, k: isize) -> isize {
    let n = n as usize;
    let index = index as usize;
    let k = k as usize;

    // We need to find the maximum sum of an increasing subsequence that:
    // 1. Ends at some index i where i <= index
    // 2. Includes the element at index k (where k > index)
    // 3. The subsequence is increasing

    // Since k > index, and the subsequence must include a[k], and be increasing,
    // we need to find an increasing subsequence ending at some i <= index such that a[i] < a[k],
    // and then add a[k] to it.

    // First, compute the maximum sum increasing subsequence ending at each position up to index.
    // Let dp[i] = maximum sum of an increasing subsequence ending at index i.

    let mut dp = vec![0isize; n];

    for i in 0..n {
        dp[i] = a[i];
        for j in 0..i {
            if a[j] < a[i] && dp[j] + a[i] > dp[i] {
                dp[i] = dp[j] + a[i];
            }
        }
    }

    // Now, find the maximum dp[i] for i <= index such that a[i] < a[k].
    // Then the answer is that maximum dp[i] + a[k].
    // If no such i exists, the answer is just a[k] (the subsequence is just [a[k]]).

    let mut max_prev = 0isize;
    let mut found = false;

    for i in 0..=index {
        if a[i] < a[k] {
            if !found || dp[i] > max_prev {
                max_prev = dp[i];
                found = true;
            }
        }
    }

    if found {
        max_prev + a[k]
    } else {
        a[k]
    }
}
