/// Write a rsthon function that takes in a non-negative number and returns the number of prime numbers less than the given non-negative number.
fn count_Primes_nums(n: isize) -> isize {
    if n <= 2 {
        return 0;
    }
    let limit = n as usize;
    let mut sieve = vec![true; limit];
    sieve[0] = false;
    sieve[1] = false;
    let mut i = 2;
    while i * i < limit {
        if sieve[i] {
            let mut j = i * i;
            while j < limit {
                sieve[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    sieve.iter().filter(|&&is_prime| is_prime).count() as isize
}
```

