/// Write a rsthon function to check whether the given vector is monotonic or not.
fn is_Monotonic(A: Vec<isize>) -> bool {
    if A.len() <= 2 {
        return true;
    }

    let mut increasing = true;
    let mut decreasing = true;

    for i in 1..A.len() {
        if A[i] > A[i - 1] {
            decreasing = false;
        }
        if A[i] < A[i - 1] {
            increasing = false;
        }
        if !increasing && !decreasing {
            return false;
        }
    }

    true
}
```

