/// You are given a vector of two strings, both strings consist of open
/// parentheses '(' or close parentheses ')' only.
/// Your job is to check if it is possible to concatenate the two strings in
/// some order, that the resulting string will be good.
/// A string S is considered to be good if and only if all parentheses in S
/// are balanced. For example: the string '(())()' is good, while the string
/// '())' is not.
/// Return 'Yes' if there's a way to make a good string, and return 'No' otherwise.
/// Examples:
/// >>> match_parens(vec![String::from("()("), String::from(")")])
/// String::from("Yes")
/// >>> match_parens(vec![String::from(")"), String::from(")")])
/// String::from("No")
fn match_parens(lst: Vec<String>) -> String {
    if lst.len() != 2 {
        return String::from("No");
    }

    let s1 = &lst[0];
    let s2 = &lst[1];

    // Check both orderings: s1 + s2 and s2 + s1
    let check_balanced = |s: &str| -> bool {
        let mut balance = 0;
        for c in s.chars() {
            if c == '(' {
                balance += 1;
            } else if c == ')' {
                balance -= 1;
            }
            if balance < 0 {
                return false;
            }
        }
        balance == 0
    };

    let combined1 = format!("{}{}", s1, s2);
    let combined2 = format!("{}{}", s2, s1);

    if check_balanced(&combined1) || check_balanced(&combined2) {
        String::from("Yes")
    } else {
        String::from("No")
    }
}
```

