/// Write a function to check whether the given number is armstrong or not.
fn armstrong_number(number: isize) -> bool {
    if number < 0 {
        return false;
    }
    let num = number as u64;
    let digits: Vec<u64> = num
        .to_string()
        .chars()
        .map(|c| c.to_digit(10).unwrap() as u64)
        .collect();
    let n = digits.len() as u64;
    let sum: u64 = digits.iter().map(|&d| d.pow(n as u32)).sum();
    sum == num
}
```

