/// Write a rsthon function to count the number of substrings with the sum of digits equal to their length.
fn count_Substrings(s: String) -> isize {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut count = 0;

    for i in 0..n {
        let mut sum = 0;
        for j in i..n {
            if let Some(digit) = chars[j].to_digit(10) {
                sum += digit as isize;
            } else {
                // If the character is not a digit, the substring can't satisfy the condition
                // since non-digit characters don't contribute to digit sum but add to length
                // Actually, let's reconsider: the problem says "sum of digits" - non-digit chars
                // have no digit value, so they contribute 0 to sum but 1 to length.
                // So sum of digits = 0 for that position, length increases by 1.
                // The condition is sum == length. If we have non-digits, sum stays same but length grows.
                // Let's just handle it: non-digit contributes 0 to sum.
                sum += 0;
            }
            let length = (j - i + 1) as isize;
            if sum == length {
                count += 1;
            }
        }
    }

    count
}
```

