/// Input is a space-delimited string of numberals from 'zero' to 'nine'.
/// Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
/// Return the string with numbers sorted from smallest to largest
/// >>> sort_numbers(String::from("three one five"))
/// String::from("one three five")
fn sort_numbers(numbers: String) -> String {
    let word_to_num: std::collections::HashMap<&str, u8> = [
        ("zero", 0),
        ("one", 1),
        ("two", 2),
        ("three", 3),
        ("four", 4),
        ("five", 5),
        ("six", 6),
        ("seven", 7),
        ("eight", 8),
        ("nine", 9),
    ].iter().cloned().collect();

    let num_to_word: std::collections::HashMap<u8, &str> = [
        (0, "zero"),
        (1, "one"),
        (2, "two"),
        (3, "three"),
        (4, "four"),
        (5, "five"),
        (6, "six"),
        (7, "seven"),
        (8, "eight"),
        (9, "nine"),
    ].iter().cloned().collect();

    let words: Vec<&str> = numbers.split_whitespace().collect();
    let mut nums: Vec<u8> = Vec::new();
    for word in words {
        if let Some(&num) = word_to_num.get(word) {
            nums.push(num);
        }
    }
    nums.sort();
    let sorted_words: Vec<String> = nums.iter().map(|n| num_to_word[n].to_string()).collect();
    sorted_words.join(" ")
}
