fn fruit_distribution(s: String, n: isize) -> isize {
    let parts: Vec<&str> = s.split_whitespace().collect();
    let mut total_apples_oranges: isize = 0;

    // Parse the string to find numbers before "apples" and "oranges"
    let words: Vec<&str> = s.split_whitespace().collect();
    let mut i = 0;
    while i < words.len() {
        if words[i] == "apples" || words[i] == "oranges" {
            if i > 0 {
                if let Ok(num) = words[i - 1].parse::<isize>() {
                    total_apples_oranges += num;
                }
            }
        }
        i += 1;
    }

    n - total_apples_oranges
