/// Write a function to find the index of the first occurrence of a given number in a sorted vector.
fn find_first_occurrence(A: Vec<isize>, x: isize) -> isize {
    let mut left = 0isize;
    let mut right = A.len() as isize - 1;
    let mut result = -1;

    while left <= right {
        let mid = left + (right - left) / 2;
        if A[mid as usize] == x {
            result = mid;
            right = mid - 1;
        } else if A[mid as usize] < x {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    result
}
```

