/// Write a function to find common first element in given vector of vectors.
fn group_tuples(Input: Vec<Vec<String>>) -> Vec<Vec<String>> {
    if Input.is_empty() {
        return vec![];
    }

    // Find the first element of the first inner vector
    let first_first = &Input[0][0];

    // Collect all inner vectors whose first element matches the first element of the first inner vector
    let mut result: Vec<Vec<String>> = Vec::new();
    for inner in Input {
        if !inner.is_empty() && inner[0] == *first_first {
            result.push(inner);
        }
    }

    result
}
```

