        return 1;
    }

    // Bell numbers can be computed using the Bell triangle or using the recurrence:
    // B(n+1) = sum_{k=0}^{n} C(n,k) * B(k)
    // We'll use dynamic programming with the recurrence.

    let mut bell = vec![0isize; n + 1];
    bell[0] = 1;
    bell[1] = 1;

    for i in 2..=n {
        let mut sum = 0;
        for k in 0..i {
            // C(i-1, k) * bell[k]
            let comb = binomial_coefficient(i - 1, k);
            sum += comb * bell[k];
        }
        bell[i] = sum;
    }

    bell[n]
}

fn binomial_coefficient(n: usize, k: usize) -> isize {
    if k > n {
        return 0;
    }
    if k == 0 || k == n {
        return 1;
    }
    let mut result = 1;
    for i in 0..k {
        result = result * (n - i) / (i + 1);
    }
    result
}
