/// Write a function that counts the number of pairs of integers in a vector that xor to an even number.
fn find_even_pair(A: Vec<isize>) -> isize {
    // XOR of two numbers is even if and only if both numbers have the same parity.
    // So we count pairs where both are even or both are odd.
    let n = A.len() as isize;
    let mut even_count = 0;
    let mut odd_count = 0;

    for &x in &A {
        if x % 2 == 0 {
            even_count += 1;
        } else {
            odd_count += 1;
        }
    }

    // Number of pairs with same parity: C(even_count, 2) + C(odd_count, 2)
    let even_pairs = even_count * (even_count - 1) / 2;
    let odd_pairs = odd_count * (odd_count - 1) / 2;

    even_pairs + odd_pairs
}
