/// Write a function that takes in a vector and length n, and generates all combinations (with repetition) of the elements of the vector and returns a vector with a vector for each combination.
fn combinations_colors(l: Vec<String>, n: isize) -> Vec<Vec<String>> {
    if n <= 0 {
        return vec![vec![]];
    }
    let n = n as usize;
    let mut result: Vec<Vec<String>> = Vec::new();
    let len = l.len();
    if len == 0 {
        return result;
    }

    // Use indices to generate combinations with repetition
    // We need to generate all sequences of length n where each element is from l,
    // and the indices are non-decreasing (to avoid duplicates and ensure combinations with repetition)

    // Start with all indices set to 0
    let mut indices: Vec<usize> = vec![0; n];

    loop {
        // Build the current combination
        let combo: Vec<String> = indices.iter().map(|&i| l[i].clone()).collect();
        result.push(combo);

        // Find the rightmost index that can be incremented
        let mut pos = n - 1;
        while pos > 0 && indices[pos] == len - 1 {
            pos -= 1;
        }

        if pos == 0 && indices[0] == len - 1 {
            break;
        }

        // Increment the index at pos and reset all indices after it
        indices[pos] += 1;
        for i in (pos + 1)..n {
            indices[i] = indices[pos];
        }
    }

    result
}
