    let ops: Vec<&str> = operator.iter().map(|s| s.as_str()).collect();

    // We'll process exponentiation first, then multiplication/division, then addition/subtraction.
    // We can do this by repeatedly scanning for the highest precedence operator and evaluating it.

    let mut operands: Vec<isize> = operand;
    let mut operators: Vec<&str> = ops;

    // Process exponentiation (**)
    let mut i = 0;
    while i < operators.len() {
        if operators[i] == "**" {
            let result = operands[i].pow(operands[i + 1] as u32);
            operands.remove(i);
            operands.remove(i);
            operands.insert(i, result);
            operators.remove(i);
            // Don't increment i, check again at same position
        } else {
            i += 1;
        }
    }

    // Process multiplication (*) and floor division (//)
    i = 0;
    while i < operators.len() {
        if operators[i] == "*" || operators[i] == "//" {
            let result = if operators[i] == "*" {
                operands[i] * operands[i + 1]
            } else {
                // Floor division: we need to handle negative numbers properly for floor division
                // In Rust, / does truncation towards zero, but floor division rounds towards negative infinity.
                // For non-negative integers, / and // are the same.
                // The problem says operands are non-negative integers, so / is fine.
                operands[i] / operands[i + 1]
            };
            operands.remove(i);
            operands.remove(i);
            operands.insert(i, result);
            operators.remove(i);
        } else {
            i += 1;
        }
    }

    // Process addition (+) and subtraction (-)
    i = 0;
    while i < operators.len() {
        if operators[i] == "+" || operators[i] == "-" {
            let result = if operators[i] == "+" {
                operands[i] + operands[i + 1]
            } else {
                operands[i] - operands[i + 1]
            };
            operands.remove(i);
            operands.remove(i);
            operands.insert(i, result);
            operators.remove(i);
        } else {
            i += 1;
        }
    }

    operands[0]
}
