/// Given a square matrix of size N*N given as a vector of vectors, where each cell is associated with a specific cost. A path is defined as a specific sequence of cells that starts from the top-left cell move only right or down and ends on bottom right cell. We want to find a path with the maximum average over all existing paths. Average is computed as total cost divided by the number of cells visited in the path.
fn maxAverageOfPath(cost: Vec<Vec<isize>>) -> f64 {
    let n = cost.len();
    if n == 0 {
        return 0.0;
    }

    // The number of cells in any path from top-left to bottom-right moving only right or down
    // is always 2*n - 1 (n steps right + n-1 steps down, plus the starting cell)
    let path_length = 2 * n - 1;

    // We want to maximize the average, which is total_cost / path_length.
    // Since path_length is constant for all paths, maximizing the average is equivalent
    // to maximizing the total cost.
    // So we just need to find the path with the maximum total cost using dynamic programming.

    // dp[i][j] = maximum total cost to reach cell (i, j) from (0, 0)
    let mut dp = vec![vec![0isize; n]; n];
    dp[0][0] = cost[0][0];

    // Fill first row
    for j in 1..n {
        dp[0][j] = dp[0][j - 1] + cost[0][j];
    }

    // Fill first column
    for i in 1..n {
        dp[i][0] = dp[i - 1][0] + cost[i][0];
    }

    // Fill the rest
    for i in 1..n {
        for j in 1..n {
            dp[i][j] = cost[i][j] + dp[i - 1][j].max(dp[i][j - 1]);
        }
    }

    let max_total_cost = dp[n - 1][n - 1];
    max_total_cost as f64 / path_length as f64
}
