/// Write a function that takes in a sorted vector, its length (n), and an element and returns whether the element is the majority element in the given sorted vector. (The majority element is the element that occurs more than n/2 times.)
fn is_majority(arr: Vec<isize>, n: isize, x: isize) -> bool {
    if n <= 0 {
        return false;
    }

    // Find the first occurrence of x using binary search
    let mut left = 0isize;
    let mut right = n - 1;
    let mut first_occurrence = -1;

    while left <= right {
        let mid = left + (right - left) / 2;
        if arr[mid as usize] == x {
            first_occurrence = mid;
            right = mid - 1;
        } else if arr[mid as usize] < x {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    if first_occurrence == -1 {
        return false;
    }

    // Find the last occurrence of x using binary search
    left = 0;
    right = n - 1;
    let mut last_occurrence = -1;

    while left <= right {
        let mid = left + (right - left) / 2;
        if arr[mid as usize] == x {
            last_occurrence = mid;
            left = mid + 1;
        } else if arr[mid as usize] < x {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    let count = last_occurrence - first_occurrence + 1;
    count > n / 2
}
