fn all_Bits_Set_In_The_Given_Range(n: isize, l: isize, r: isize) -> bool {
    // Check if the range is valid
    if l < 1 || r < l || r > 64 {
        return false;
    }

    // Create a mask with bits set from position l to r (1-indexed)
    // Bit positions are 1-indexed from the right (LSB is position 1)
    let width = r - l + 1;
    let mask = ((1i64 << width) - 1) << (l - 1);

    // Check if all bits in the range are unset (i.e., n & mask == 0)
    (n as i64 & mask) == 0
}
