        return Vec::new();
    }

    let first = array[0];
    let last = array[array.len() - 1];
    let sum = first + last;

    let mut sorted = array;
    sorted.sort();

    if sum % 2 == 0 {
        // Even sum: sort in descending order
        sorted.reverse();
    }
    // Odd sum: already sorted in ascending order

