fn is_sorted(lst: Vec<isize>) -> bool {
    if lst.len() <= 1 {
        return true;
    }

    // Check if sorted in ascending order
    for i in 1..lst.len() {
        if lst[i] < lst[i - 1] {
            return false;
        }
    }

    // Check for more than 1 duplicate of the same number
    // i.e., if any number appears more than twice, return false
    let mut count_map: std::collections::HashMap<isize, usize> = std::collections::HashMap::new();
    for &num in &lst {
        *count_map.entry(num).or_insert(0) += 1;
        if *count_map.get(&num).unwrap() > 2 {
            return false;
        }
    }

    true
