/// You are given a positive integer n. You have to create an integer vector a of length n.
/// For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
/// Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
/// and a[i] + a[j] + a[k] is a multiple of 3.
/// Example :
/// >>> get_max_triples(5)
/// 1
/// Explanation: 
/// a = [1, 3, 7, 13, 21]
/// The only valid triple is (1, 7, 13).
fn get_max_triples(n: isize) -> isize {
    if n < 3 {
        return 0;
    }

    // Count how many elements have a[i] % 3 == 0, 1, or 2
    let mut count0: isize = 0;
    let mut count1: isize = 0;
    let mut count2: isize = 0;

    for i in 1..=n {
        let val = i * i - i + 1;
        let rem = ((val % 3) + 3) % 3;
        match rem {
            0 => count0 += 1,
            1 => count1 += 1,
            2 => count2 += 1,
            _ => unreachable!(),
        }
    }

    // We need a[i] + a[j] + a[k] ≡ 0 (mod 3)
    // Possible combinations of remainders (r1, r2, r3) such that r1 + r2 + r3 ≡ 0 mod 3:
    // (0, 0, 0): C(count0, 3)
    // (1, 1, 1): C(count1, 3)
    // (2, 2, 2): C(count2, 3)
    // (0, 1, 2): count0 * count1 * count2

    let mut result: isize = 0;

    // C(count0, 3)
    if count0 >= 3 {
        result += count0 * (count0 - 1) * (count0 - 2) / 6;
    }
    // C(count1, 3)
    if count1 >= 3 {
        result += count1 * (count1 - 1) * (count1 - 2) / 6;
    }
    // C(count2, 3)
    if count2 >= 3 {
        result += count2 * (count2 - 1) * (count2 - 2) / 6;
    }
    // (0, 1, 2)
    result += count0 * count1 * count2;

    result
}
