/// Write a function to find the nth number in the newman conway sequence.
fn sequence(n: isize) -> isize {
    if n <= 0 {
        return 0;
    }
    if n == 1 || n == 2 {
        return 1;
    }
    let mut memo = vec![0; (n + 1) as usize];
    memo[1] = 1;
    memo[2] = 1;
    for i in 3..=n as usize {
        let prev = memo[memo[i - 1] as usize];
        memo[i] = prev;
    }
    memo[n as usize]
}
