                None => {
                    smallest_even = Some(val);
                    smallest_index = Some(i);
                }
                Some(current_smallest) => {
                    if val < current_smallest {
                        smallest_even = Some(val);
                        smallest_index = Some(i);
                    }
                }
            }
        }
    }

    match (smallest_even, smallest_index) {
        (Some(val), Some(idx)) => vec![val, idx as isize],
        _ => Vec::new(),
    }
