fn lcs_of_three(X: String, Y: String, Z: String) -> isize {
    let x_chars: Vec<char> = X.chars().collect();
    let y_chars: Vec<char> = Y.chars().collect();
    let z_chars: Vec<char> = Z.chars().collect();
    let m = x_chars.len();
    let n = y_chars.len();
    let p = z_chars.len();

    let mut dp = vec![vec![vec![0isize; p + 1]; n + 1]; m + 1];

    for i in 0..=m {
        for j in 0..=n {
            for k in 0..=p {
                if i == 0 || j == 0 || k == 0 {
                    dp[i][j][k] = 0;
                } else if x_chars[i - 1] == y_chars[j - 1] && y_chars[j - 1] == z_chars[k - 1] {
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1;
                } else {
                    dp[i][j][k] = dp[i - 1][j][k].max(dp[i][j - 1][k]).max(dp[i][j][k - 1]);
                }
            }
        }
    }

    dp[m][n][p]
}
