/// You are given two intervals,
/// where each interval is a pair of integers. For example, interval = (start, end) = (1, 2).
/// The given intervals are closed which means that the interval (start, end)
/// includes both start and end.
/// For each given interval, it is assumed that its start is less or equal its end.
/// Your task is to determine whether the length of intersection of these two 
/// intervals is a prime number.
/// Example, the intersection of the intervals (1, 3), (2, 4) is (2, 3)
/// which its length is 1, which not a prime number.
/// If the length of the intersection is a prime number, return "YES",
/// otherwise, return "NO".
/// If the two intervals don't intersect, return "NO".
/// [input/output] samples:
/// >>> intersection((1, 2), (2, 3))
/// String::from("NO")
/// >>> intersection((-1, 1), (0, 4))
/// String::from("NO")
/// >>> intersection((-3, -1), (-5, 5))
/// String::from("YES")
fn intersection(interval1: (isize, isize), interval2: (isize, isize)) -> String {
    let (start1, end1) = interval1;
    let (start2, end2) = interval2;

    // Find the intersection
    let inter_start = start1.max(start2);
    let inter_end = end1.min(end2);

    // If no intersection
    if inter_start > inter_end {
        return String::from("NO");
    }

    // Length of intersection: number of integers in [inter_start, inter_end]
    // The length as described in the example: intersection of (1,3) and (2,4) is (2,3), length is 1.
    // (2,3) contains integers 2 and 3, so count is 2, but length is said to be 1.
    // So length = inter_end - inter_start
    let length = inter_end - inter_start;

    // Check if length is a prime number
    if length < 2 {
        return String::from("NO");
    }

    if is_prime(length) {
        String::from("YES")
    } else {
        String::from("NO")
    }
}

fn is_prime(n: isize) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}
