        return true;
    }

    let mut increasing = true;
    let mut decreasing = true;

    for i in 1..l.len() {
        if l[i] > l[i - 1] {
            decreasing = false;
        }
        if l[i] < l[i - 1] {
            increasing = false;
        }
        if !increasing && !decreasing {
            return false;
        }
    }

    true
}
