/// Write a function that takes in positive integers m and n and finds the number of possible sequences of length n, such that each element is a positive integer and is greater than or equal to twice the previous element but less than or equal to m.
fn get_total_number_of_sequences(m: isize, n: isize) -> isize {
    if n == 0 {
        return 1;
    }
    if m <= 0 || n <= 0 {
        return 0;
    }

    // dp[i][j] = number of sequences of length i ending with value j
    // We want sum of dp[n][j] for j from 1 to m
    // dp[1][j] = 1 for all j from 1 to m
    // dp[i][j] = sum of dp[i-1][k] for all k such that 2*k <= j, i.e., k <= j/2
    // So dp[i][j] = sum of dp[i-1][k] for k from 1 to j/2

    let m = m as usize;
    let n = n as usize;

    // Use two rows to save space
    let mut prev = vec![0usize; m + 1];
    let mut curr = vec![0usize; m + 1];

    // Base case: sequences of length 1
    for j in 1..=m {
        prev[j] = 1;
    }

    for i in 2..=n {
        // Compute prefix sums of prev to quickly get sum from 1 to j/2
        let mut prefix = vec![0usize; m + 1];
        for j in 1..=m {
            prefix[j] = prefix[j - 1] + prev[j];
        }
        for j in 1..=m {
            let max_k = j / 2;
            curr[j] = if max_k >= 1 { prefix[max_k] } else { 0 };
        }
        std::mem::swap(&mut prev, &mut curr);
    }

    let mut total: usize = 0;
    for j in 1..=m {
        total += prev[j];
    }

    total as isize
}
