fn minSubArraySum(nums: Vec<isize>) -> isize {
    let mut min_sum = nums[0];
    let mut current_sum = nums[0];
    for &num in &nums[1..] {
        current_sum = std::cmp::min(num, current_sum + num);
        min_sum = std::cmp::min(min_sum, current_sum);
    }
    min_sum
