fn simplify(x: String, n: String) -> bool {
    let parse_fraction = |s: &str| -> (u64, u64) {
        let parts: Vec<&str> = s.split('/').collect();
        let num: u64 = parts[0].parse().unwrap();
        let den: u64 = parts[1].parse().unwrap();
        (num, den)
    };

    let (x_num, x_den) = parse_fraction(&x);
    let (n_num, n_den) = parse_fraction(&n);

    // x * n = (x_num * n_num) / (x_den * n_den)
    // We need to check if this is a whole number, i.e., (x_den * n_den) divides (x_num * n_num)
    let numerator = x_num * n_num;
    let denominator = x_den * n_den;

    numerator % denominator == 0
}
