/// Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
/// >>> fizz_buzz(50)
/// 0
/// >>> fizz_buzz(78)
/// 2
/// >>> fizz_buzz(79)
/// 3
fn fizz_buzz(n: isize) -> isize {
    let mut count = 0;
    for i in 1..n {
        if i % 11 == 0 || i % 13 == 0 {
            let mut num = i;
            if num < 0 {
                num = -num;
            }
            if num == 0 {
                continue;
            }
            let mut temp = num;
            while temp > 0 {
                if temp % 10 == 7 {
                    count += 1;
                }
                temp /= 10;
            }
        }
    }
    count
