/// Write a function to get all lucid numbers smaller than or equal to a given integer.
fn get_ludic(n: isize) -> Vec<isize> {
    if n < 1 {
        return vec![];
    }

    let mut numbers: Vec<isize> = (1..=n).collect();
    let mut i = 0;

    while i < numbers.len() {
        let step = numbers[i];
        // Remove every step-th element starting from index i+1
        let mut j = i + 1;
        while j < numbers.len() {
            if (j - i) % step as usize == 0 {
                numbers.remove(j);
            } else {
                j += 1;
            }
        }
        i += 1;
    }

    numbers
}
