fn amicable_numbers_sum(limit: isize) -> isize {
    fn sum_of_divisors(n: isize) -> isize {
        if n <= 1 {
            return 0;
        }
        let mut sum = 1;
        let mut i = 2;
        while i * i <= n {
            if n % i == 0 {
                sum += i;
                if i != n / i {
                    sum += n / i;
                }
            }
            i += 1;
        }
        sum
    }

    let mut total = 0;
    for n in 2..=limit {
        let d_n = sum_of_divisors(n);
        if d_n > n && d_n <= limit {
            let d_d_n = sum_of_divisors(d_n);
            if d_d_n == n {
                total += n;
            }
        }
    }
    total
