/// Given the lengths of the three sides of a triangle. Return true if the three
/// sides form a right-angled triangle, false otherwise.
/// A right-angled triangle is a triangle in which one angle is right angle or 
/// 90 degree.
/// Example:
/// >>> right_angle_triangle(3, 4, 5)
/// true
/// >>> right_angle_triangle(1, 2, 3)
/// false
fn right_angle_triangle(a: isize, b: isize, c: isize) -> bool {
    // First, check if the sides can form a valid triangle
    // The sum of any two sides must be greater than the third side
    if a <= 0 || b <= 0 || c <= 0 {
        return false;
    }
    if a + b <= c || a + c <= b || b + c <= a {
        return false;
    }

    // Sort the sides so that c is the largest (hypotenuse candidate)
    let mut sides = [a, b, c];
    sides.sort();
    let (a, b, c) = (sides[0], sides[1], sides[2]);

    // Check Pythagorean theorem: a^2 + b^2 == c^2
    a * a + b * b == c * c
}
