/// Write a rsthon function to find the element that appears only once in a sorted vector.
fn search(arr: Vec<isize>) -> isize {
    let mut left = 0;
    let mut right = arr.len() - 1;

    while left < right {
        let mid = left + (right - left) / 2;
        // If mid is even, the pair should start at mid
        // If mid is odd, the pair should start at mid - 1
        let pair_start = if mid % 2 == 0 { mid } else { mid - 1 };

        if arr[pair_start] == arr[pair_start + 1] {
            // The single element is in the right half
            left = mid + 1;
        } else {
            // The single element is in the left half (including mid)
            right = mid;
        }
    }

    arr[left]
}
