/// base numbers are less than 10.
/// >>> change_base(8, 3)
/// String::from("22")
/// >>> change_base(8, 2)
/// String::from("1000")
/// >>> change_base(7, 2)
/// String::from("111")
fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return String::from("0");
    }

    let mut num = x.abs();
    let mut result = String::new();
    let mut negative = x < 0;

    while num > 0 {
        let remainder = (num % base) as usize;
        result.insert(0, char::from_digit(remainder as u32, 10).unwrap());
        num /= base;
    }

    if negative {
        result.insert(0, '-');
    }

    result
}
