/// Write a function to find the Eulerian number a(n, m).
fn eulerian_num(n: isize, m: isize) -> isize {
    if n < 0 || m < 0 || m >= n {
        return 0;
    }
    if n == 0 && m == 0 {
        return 1;
    }
    // Use dynamic programming with a 2D table
    // Eulerian numbers satisfy: A(n, m) = (m+1)*A(n-1, m) + (n-m)*A(n-1, m-1)
    let n = n as usize;
    let m = m as usize;

    // Create a 2D vector for DP
    let mut dp = vec![vec![0usize; n]; n];

    // Base case: A(1, 0) = 1
    if n >= 1 {
        dp[0][0] = 1;
    }

    for i in 1..n {
        for j in 0..=i.min(m) {
            let term1 = if j < i {
                ((j as usize + 1) as usize) * dp[i - 1][j]
            } else {
                0
            };
            let term2 = if j > 0 {
                ((i as usize - j + 1) as usize) * dp[i - 1][j - 1]
            } else {
                0
            };
            dp[i][j] = term1 + term2;
        }
    }

    dp[n - 1][m] as isize
}
