```rust
/// Write a function to find k number of smallest pairs which consist of one element from the first vector and one element from the second vector.
fn k_smallest_pairs(nums1: Vec<isize>, nums2: Vec<isize>, k: isize) -> Vec<Vec<isize>> {
    if nums1.is_empty() || nums2.is_empty() || k <= 0 {
        return vec![];
    }

    let k = k as usize;
    let n1 = nums1.len();
    let n2 = nums2.len();

    // Use a min-heap (priority queue) to efficiently find the k smallest pairs
    // We use BinaryHeap with Reverse to simulate a min-heap
    use std::collections::BinaryHeap;
    use std::cmp::Reverse;

    // Each element in the heap: (sum, index1, index2)
    let mut heap = BinaryHeap::new();

    // Initialize the heap with the first element from nums2 paired with each element from nums1
    // Actually, a better approach: start with (0, 0) and then expand
    // Push (nums1[0] + nums2[0], 0, 0) into the heap
    heap.push(Reverse((nums1[0] + nums2[0], 0, 0)));

    let mut result = Vec::new();
    let mut visited = std::collections::HashSet::new();
    visited.insert((0, 0));

    while result.len() < k && !heap.is_empty() {
        let Reverse((sum, i, j)) = heap.pop().unwrap();
        result.push(vec![nums1[i], nums2[j]]);

        // Try moving to the next element in nums2 (i, j+1)
        if j + 1 < n2 {
            let next = (i, j + 1);
            if visited.insert(next) {
                heap.push(Reverse((nums1[i] + nums2[j + 1], i, j + 1)));
            }
        }

        // Try moving to the next element in nums1 (i+1, 0) but only if j == 0
        // This ensures we don't miss any pairs and avoids duplicates
        if j == 0 && i + 1 < n1 {
            let next = (i + 1, 0);
            if visited.insert(next) {
                heap.push(Reverse((nums1[i + 1] + nums2[0], i + 1, 0)));
            }
        }
    }

    result
}
