/// Write a function to find the first adverb and their positions in a given sentence.
fn find_adverb_position(text: String) -> (isize, isize, String) {
    // Common adverb suffixes in English
    let adverb_suffixes = vec!["ly", "ily", "ally", "ely", "ily", "ily"];

    let words: Vec<&str> = text.split_whitespace().collect();

    for (i, word) in words.iter().enumerate() {
        let word_lower = word.to_lowercase();
        for suffix in &adverb_suffixes {
            if word_lower.ends_with(suffix) {
                // Calculate the byte position of the word in the original string
                let mut pos = 0;
                let mut found = false;
                for (j, w) in words.iter().enumerate() {
                    if j == i {
                        found = true;
                        break;
                    }
                    pos += w.len() + 1; // +1 for the space
                }
                if found {
                    return (pos as isize, (pos + word.len()) as isize, word.to_string());
                }
            }
        }
    }

    // If no adverb found, return default values
    (-1, -1, String::new())
}
