/// note last.
/// Here is a legend:
/// 'o' - whole note, lasts four beats
/// 'o|' - half note, lasts two beats
/// '.|' - quarter note, lasts one beat
/// >>> parse_music(String::from("o o| .| o| o| .| .| .| .| o o"))
/// vec![4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
fn parse_music(music_string: String) -> Vec<isize> {
    let mut beats = Vec::new();
    let chars: Vec<char> = music_string.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == 'o' {
            // Check if it's "o|" (half note) or just "o" (whole note)
            if i + 1 < chars.len() && chars[i + 1] == '|' {
                beats.push(2);
                i += 2;
            } else {
                beats.push(4);
                i += 1;
            }
        } else if chars[i] == '.' {
            // It should be ".|" (quarter note)
            if i + 1 < chars.len() && chars[i + 1] == '|' {
                beats.push(1);
                i += 2;
            } else {
                // Skip unexpected characters
                i += 1;
            }
        } else {
            // Skip spaces or other characters
            i += 1;
        }
    }
    beats
