fn minPath(grid: Vec<Vec<isize>>, k: isize) -> Vec<isize> {
    let n = grid.len();
    let k = k as usize;

    // Find the position of the smallest value (which is 1)
    // Since all values 1..=N*N appear exactly once, the minimum path will start with 1
    // because any path starting with a larger value would be lexicographically larger.

    // Find where 1 is located
    let mut start_r = 0;
    let mut start_c = 0;
    for r in 0..n {
        for c in 0..n {
            if grid[r][c] == 1 {
                start_r = r;
                start_c = c;
            }
        }
    }

    // We need to find the lexicographically smallest path of length k starting from (start_r, start_c)
    // At each step, we choose the neighbor with the smallest value.
    // But wait - we need to consider that the path is of length k, meaning k cells visited.
    // The first cell is fixed as the cell with value 1.
    // For subsequent cells, we greedily pick the smallest neighbor? 
    // Actually, since we want the lexicographically smallest sequence, and the first element is fixed (1),
    // we need to minimize the second element, then the third, etc.
    // At each step, among all reachable neighbors, we pick the one with the smallest value.
    // But we need to be careful: picking the smallest neighbor now might lead to a worse future.
    // However, for lexicographic order, we always want the smallest possible value at the current position,
    // regardless of future positions. So greedy works.

    let mut path = Vec::with_capacity(k);
    path.push(1);

    let mut r = start_r;
    let mut c = start_c;

    for _ in 1..k {
        // Find the neighbor with the smallest value
        let mut best_val = isize::MAX;
        let mut best_r = r;
        let mut best_c = c;

        // Check all 4 neighbors
        let directions = [(0, 1), (0, -1), (1, 0), (-1, 0)];
        for (dr, dc) in &directions {
            let nr = r as isize + dr;
            let nc = c as isize + dc;
            if nr >= 0 && nr < n as isize && nc >= 0 && nc < n as isize {
                let val = grid[nr as usize][nc as usize];
                if val < best_val {
                    best_val = val;
                    best_r = nr as usize;
                    best_c = nc as usize;
                }
            }
        }

        path.push(best_val);
        r = best_r;
        c = best_c;
    }

    path
}
