    // Let's verify: tri(2) = 1 + 2/2 = 2 ✓
    // tri(4) = 1 + 4/2 = 3
    // tri(3) = tri(2) + tri(1) + tri(4) = 2 + 3 + 3 = 8 ✓

    // So we need to compute tri(0) through tri(n).
    // tri(0) = 1 (given by the example)
    // tri(1) = 3 (given)
    // For even n >= 2: tri(n) = 1 + n/2
    // For odd n >= 3: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)

    // The tricky part is that for odd n, tri(n) depends on tri(n+1), which is even.
    // So we can compute tri(n+1) first (since it's even), then use it to compute tri(n).

    // Let's build the sequence iteratively.
    // We need tri(0), tri(1), ..., tri(n).

    let mut result: Vec<isize> = Vec::new();

    if n >= 0 {
        result.push(1); // tri(0)
    }
    if n >= 1 {
        result.push(3); // tri(1)
    }

    // Now compute tri(2) through tri(n)
    let mut i = 2;
    while i <= n {
        if i % 2 == 0 {
            // Even: tri(i) = 1 + i / 2
            let val = 1 + i / 2;
            result.push(val);
        } else {
            // Odd: tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
            // tri(i+1) is even, so we can compute it
            let tri_i_plus_1 = 1 + (i + 1) / 2;
