/// Write a function to find the nth newman–shanks–williams prime number.
fn newman_prime(n: isize) -> isize {
    if n <= 0 {
        return 0;
    }

    // The Newman-Shanks-Williams (NSW) numbers are defined by the recurrence:
    // S(0) = 1, S(1) = 1, S(n) = 2*S(n-1) + S(n-2) for n >= 2
    // The NSW primes are the NSW numbers that are also prime.
    // We need to find the nth NSW prime.

    // Generate NSW numbers and check for primality until we find n primes.
    let mut count: isize = 0;
    let mut i: isize = 0;

    loop {
        let s = nsw_number(i);
        if is_prime(s) {
            count += 1;
            if count == n {
                return s;
            }
        }
        i += 1;
    }
}

/// Compute the nth NSW number.
/// S(0) = 1, S(1) = 1, S(n) = 2*S(n-1) + S(n-2)
fn nsw_number(n: isize) -> isize {
    if n <= 0 {
        return 1;
    }
    if n == 1 {
        return 1;
    }

    let mut a: isize = 1; // S(0)
    let mut b: isize = 1; // S(1)

    for _ in 2..=n {
        let c = 2 * b + a;
        a = b;
        b = c;
    }

    b
}

/// Check if a number is prime.
fn is_prime(n: isize) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i: isize = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}
