/// Write a rsthon function to find the sum of the per-digit difference between two integers.
fn digit_distance_nums(n1: isize, n2: isize) -> isize {
    let digits1: Vec<u32> = n1.unsigned_abs().to_string().chars().map(|c| c.to_digit(10).unwrap()).collect();
    let digits2: Vec<u32> = n2.unsigned_abs().to_string().chars().map(|c| c.to_digit(10).unwrap()).collect();

    let max_len = digits1.len().max(digits2.len());
    let mut sum = 0;

    for i in 0..max_len {
        let d1 = if i < digits1.len() { digits1[i] } else { 0 };
        let d2 = if i < digits2.len() { digits2[i] } else { 0 };
        sum += (d1 as isize - d2 as isize).unsigned_abs() as isize;
    }

    sum
}
