fn find_combinations(test_list: Vec<(isize, isize)>) -> Vec<(isize, isize)> {
    let mut result: Vec<(isize, isize)> = Vec::new();
    let n = test_list.len();

    // Generate all possible combinations of tuples
    for i in 0..n {
        for j in i..n {
            let sum = (test_list[i].0 + test_list[j].0, test_list[i].1 + test_list[j].1);
            result.push(sum);
        }
    }

    // Remove duplicates while preserving order
    let mut seen: Vec<(isize, isize)> = Vec::new();
    for item in result {
        if !seen.contains(&item) {
            seen.push(item);
        }
    }

    seen
}
