/// Write a function to count those characters which have vowels as their neighbors in the given string.
fn count_vowels(test_str: String) -> isize {
    let chars: Vec<char> = test_str.chars().collect();
    let len = chars.len();
    let mut count = 0;

    for i in 0..len {
        let is_vowel = |c: char| matches!(c.to_ascii_lowercase(), 'a' | 'e' | 'i' | 'o' | 'u');

        let left_is_vowel = if i > 0 { is_vowel(chars[i - 1]) } else { false };
        let right_is_vowel = if i < len - 1 { is_vowel(chars[i + 1]) } else { false };

        if left_is_vowel && right_is_vowel {
            count += 1;
        }
    }

    count
}
