/// Given a positive integer n, return the count of the numbers of n-digit
/// positive integers that start or end with 1.
fn starts_one_ends(n: isize) -> isize {
    if n <= 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }
    // n-digit numbers: first digit from 1-9, remaining n-1 digits from 0-9
    // Total n-digit numbers: 9 * 10^(n-1)
    // Numbers starting with 1: 1 * 10^(n-1)
    // Numbers ending with 1: 9 * 10^(n-2) (first digit 1-9, last digit 1, middle n-2 digits 0-9)
    // Numbers starting AND ending with 1: 1 * 10^(n-2) (first digit 1, last digit 1, middle n-2 digits 0-9)
    // By inclusion-exclusion: start_with_1 + end_with_1 - start_and_end_with_1
    // = 10^(n-1) + 9 * 10^(n-2) - 10^(n-2)
    // = 10^(n-1) + 8 * 10^(n-2)

    let pow_n_minus_1 = 10i64.pow((n - 1) as u32);
    let pow_n_minus_2 = 10i64.pow((n - 2) as u32);

    let result = pow_n_minus_1 + 8 * pow_n_minus_2;
    result as isize
}
```

