/// Write a function to sort the given vector.
fn heap_sort(iterable: Vec<isize>) -> Vec<isize> {
    let mut arr = iterable;
    let n = arr.len();

    if n == 0 {
        return arr;
    }

    // Build max heap
    for i in (0..n / 2).rev() {
        heapify(&mut arr, n, i);
    }

    // Extract elements one by one
    for i in (1..n).rev() {
        arr.swap(0, i);
        heapify(&mut arr, i, 0);
    }

    arr
}

fn heapify(arr: &mut Vec<isize>, n: usize, i: usize) {
    let mut largest = i;
    let left = 2 * i + 1;
    let right = 2 * i + 2;

    if left < n && arr[left] > arr[largest] {
        largest = left;
    }

    if right < n && arr[right] > arr[largest] {
        largest = right;
    }

    if largest != i {
        arr.swap(i, largest);
        heapify(arr, n, largest);
    }
}
```

