        - extensions[0].chars().filter(|c| c.is_lowercase()).count() as i32;

    for ext in &extensions[1..] {
        let cap = ext.chars().filter(|c| c.is_uppercase()).count() as i32;
        let sm = ext.chars().filter(|c| c.is_lowercase()).count() as i32;
        let strength = cap - sm;
