/// Write a rsthon function to toggle bits of the number except the first and the last bit. https://www.geeksforgeeks.org/toggle-bits-number-expect-first-last-bits/
fn toggle_middle_bits(n: isize) -> isize {
    if n <= 0 {
        return n;
    }

    // Find the number of bits in n
    let mut temp = n;
    let mut num_bits = 0;
    while temp > 0 {
        num_bits += 1;
        temp >>= 1;
    }

    // If there are 2 or fewer bits, no middle bits to toggle
    if num_bits <= 2 {
        return n;
    }

    // Create a mask with all 1s except the first and last bit
    // All 1s mask: (1 << num_bits) - 1
    // Then subtract 1 (to clear last bit) and subtract (1 << (num_bits - 1)) (to clear first bit)
    // Or equivalently: ((1 << (num_bits - 2)) - 1) << 1
    let middle_mask = ((1i64 << (num_bits - 2)) - 1) << 1;

    // Apply XOR with the middle mask
    (n as i64 ^ middle_mask) as isize
}
