/// Write a rsthon function to count the number of rotations required to generate a sorted vector. https://www.geeksforgeeks.org/count-of-rotations-required-to-generate-a-sorted-vector/
fn count_rotation(arr: Vec<isize>) -> isize {
    let n = arr.len();
    if n == 0 {
        return 0;
    }
    let mut low = 0;
    let mut high = n - 1;

    // If the array is already sorted (no rotation or full rotation)
    if arr[low] <= arr[high] {
        return low as isize;
    }

    while low <= high {
        let mid = low + (high - low) / 2;
        let next = (mid + 1) % n;
        let prev = (mid + n - 1) % n;

        // Check if mid is the minimum element
        if arr[mid] <= arr[next] && arr[mid] <= arr[prev] {
            return mid as isize;
        }

        // Decide which half to search
        if arr[mid] <= arr[high] {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    0
}
