/// Write a function to sort a vector of elements.
fn comb_sort(nums: Vec<isize>) -> Vec<isize> {
    let mut nums = nums;
    let n = nums.len();
    if n <= 1 {
        return nums;
    }

    let mut gap = n;
    let shrink = 1.3;
    let mut sorted = false;

    while !sorted {
        // Update the gap value for the next comb
        gap = (gap as f64 / shrink) as usize;
        if gap <= 1 {
            gap = 1;
            sorted = true;
        }

        let mut i = 0;
        while i + gap < n {
            if nums[i] > nums[i + gap] {
                nums.swap(i, i + gap);
                sorted = false;
            }
            i += 1;
        }
    }

    nums
}
```

