/// Write a function to check whether a given string is a decimal number with a precision of 2.
fn is_decimal(num: String) -> bool {
    // Check if the string matches the pattern of a decimal number with exactly 2 decimal places
    // Valid formats: "123.45", "0.00", "1234.56", etc.
    // Must have exactly one decimal point, with exactly 2 digits after it
    // Optional leading minus sign

    let bytes = num.as_bytes();

    if bytes.is_empty() {
        return false;
    }

    let mut start = 0;

    // Handle optional negative sign
    if bytes[0] == b'-' {
        start = 1;
    }

    if start >= bytes.len() {
        return false;
    }

    // Find the decimal point
    let mut dot_pos = None;
    for i in start..bytes.len() {
        if bytes[i] == b'.' {
            dot_pos = Some(i);
            break;
        }
    }

    match dot_pos {
        Some(pos) => {
            // There must be exactly 2 digits after the decimal point
            let after_dot = &bytes[pos + 1..];
            if after_dot.len() != 2 {
                return false;
            }

            // Check that the 2 digits after the dot are actual digits
            for &b in after_dot {
                if !b.is_ascii_digit() {
                    return false;
                }
            }

            // Check that everything before the dot (excluding sign) is digits
            for i in start..pos {
                if !bytes[i].is_ascii_digit() {
                    return false;
                }
            }

            // There must be at least one digit before the dot
            if pos == start {
                return false;
            }

            true
        }
        None => {
            // No decimal point, so it's not a decimal number with precision 2
            false
        }
    }
}
