/// Write a function to calculate whether the matrix is a magic square.
fn magic_square_test(my_matrix: Vec<Vec<isize>>) -> bool {
    let n = my_matrix.len();
    if n == 0 {
        return false;
    }
    // Check that all rows have the same length and it's a square matrix
    for row in &my_matrix {
        if row.len() != n {
            return false;
        }
    }

    // Calculate the magic constant (sum of the first row)
    let magic_sum: isize = my_matrix[0].iter().sum();

    // Check that all rows sum to magic_sum
    for row in &my_matrix {
        if row.iter().sum::<isize>() != magic_sum {
            return false;
        }
    }

    // Check that all columns sum to magic_sum
    for j in 0..n {
        let col_sum: isize = (0..n).map(|i| my_matrix[i][j]).sum();
        if col_sum != magic_sum {
            return false;
        }
    }

