/// Write a function to find out the number of ways of painting the fence such that at most 2 adjacent posts have the same color for the given fence with n posts and k colors.
fn count_no_of_ways(n: isize, k: isize) -> isize {
    if n <= 0 {
        return 0;
    }
    if k <= 0 {
        return 0;
    }
    if n == 1 {
        return k;
    }
    if n == 2 {
        return k * k;
    }

    // dp[i][0] = number of ways where post i has same color as post i-1
    // dp[i][1] = number of ways where post i has different color from post i-1
    // For i=2 (0-indexed, so posts 0 and 1):
    //   same: k * 1 (post 0: k choices, post 1: same as post 0 = 1 choice)
    //   diff: k * (k-1) (post 0: k choices, post 1: different from post 0 = k-1 choices)

    let mut same: isize = k;
    let mut diff: isize = k * (k - 1);

    for _ in 3..=n {
        let new_same = diff; // To have same as previous, previous must have been different
        let new_diff = (same + diff) * (k - 1); // To have different, previous could be same or different, and we pick a different color
        same = new_same;
        diff = new_diff;
    }

    same + diff
}
