/// Write a function to find the directrix of a parabola.
fn parabola_directrix(a: isize, b: isize, c: isize) -> isize {
    // For a parabola y = ax^2 + bx + c, the directrix is y = c - (b^2 + 1) / (4a)
    // But since we're returning isize, we need to compute this carefully.
    // The vertex y-coordinate is c - b^2/(4a)
    // The directrix is y = vertex_y - 1/(4a) = c - b^2/(4a) - 1/(4a) = c - (b^2 + 1)/(4a)
    // We need to return the directrix value as an isize, so we compute (b^2 + 1) / (4a) and subtract from c.
    // Using integer division, we need to be careful with signs.

    let numerator = b * b + 1;
    let denominator = 4 * a;

    // Compute numerator / denominator with proper rounding for the directrix
    // The directrix y = c - (b^2 + 1)/(4a)
    // We need to compute this as an integer. Let's use floating point for accuracy then truncate.
    let directrix = c as f64 - (numerator as f64) / (denominator as f64);

    directrix.round() as isize
}
