/// Write a function to sort a vector of elements.
fn pancake_sort(nums: Vec<isize>) -> Vec<isize> {
    let mut arr = nums;
    let n = arr.len();

    for curr_size in (2..=n).rev() {
        // Find the index of the maximum element in arr[0..curr_size]
        let mut max_idx = 0;
        for i in 1..curr_size {
            if arr[i] > arr[max_idx] {
                max_idx = i;
            }
        }

        // If the maximum element is not already at the end, flip it to the front and then to the end
        if max_idx != curr_size - 1 {
            // Flip the maximum element to the front
            arr[..=max_idx].reverse();
            // Flip it from the front to its correct position
            arr[..curr_size].reverse();
        }
    }

    arr
}
