/// Write a rsthon function to find the sum of common divisors of two given numbers.
fn sum(a: isize, b: isize) -> isize {
    let a = a.abs();
    let b = b.abs();
    let mut result = 0;
    let mut i = 1;
    while i * i <= a.min(b) {
        if a % i == 0 && b % i == 0 {
            result += i;
            if i != a / i && i != b / i && a / i == b / i {
                result += a / i;
            }
        }
        i += 1;
    }
    result
}
