/// Write a function to find the median of two sorted vectors of same size.
fn get_median(arr1: Vec<isize>, arr2: Vec<isize>, n: isize) -> f64 {
    let n = n as usize;
    let mut merged = Vec::with_capacity(2 * n);
    let mut i = 0;
    let mut j = 0;

    while i < n && j < n {
        if arr1[i] <= arr2[j] {
            merged.push(arr1[i]);
            i += 1;
        } else {
            merged.push(arr2[j]);
            j += 1;
        }
    }

    while i < n {
        merged.push(arr1[i]);
        i += 1;
    }

    while j < n {
        merged.push(arr2[j]);
        j += 1;
    }

    let total = 2 * n;
    if total % 2 == 0 {
        let mid = total / 2;
        let val1 = merged[mid - 1] as f64;
        let val2 = merged[mid] as f64;
        (val1 + val2) / 2.0
    } else {
        merged[total / 2] as f64
    }
}
