```rust
/// Circular shift the digits of the integer x, shift the digits right by shift
/// and return the result as a string.
/// If shift > number of digits, return digits reversed.
/// >>> circular_shift(12, 1)
/// String::from("21")
/// >>> circular_shift(12, 2)
/// String::from("12")
fn circular_shift(x: isize, shift: isize) -> String {
    let s = x.to_string();
    let digits: Vec<char> = s.chars().collect();
    let n = digits.len();

    if n == 0 {
        return String::from("");
    }

    // If shift > number of digits, return digits reversed
    if shift > n as isize {
        let reversed: String = digits.iter().rev().collect();
        return reversed;
    }

    // Circular shift right by shift positions
    // Right shift by k means the last k digits move to the front
    let shift = shift as usize;
    let k = shift % n;

    if k == 0 {
        return s;
    }

    // Right circular shift: last k chars go to front
    let (prefix, suffix) = digits.split_at(n - k);
    let mut result: String = suffix.iter().collect::<String>();
    result.push_str(&prefix.iter().collect::<String>());

    result
}
