/// Write a function which sorts the given vector of integers
/// in ascending order according to the sum of their digits.
/// Note: if there are several items with similar sum of their digits,
/// order them based on their index in original vector.
/// For example:
/// >>> order_by_points(vec![1, 11, -1, -11, -12])
/// vec![-1, -11, 1, -12, 11]
/// >>> order_by_points(vec![])
/// Vec::<isize>::new()
fn order_by_points(nums: Vec<isize>) -> Vec<isize> {
    let mut indexed: Vec<(isize, usize)> = nums.into_iter().enumerate().collect();
    indexed.sort_by(|a, b| {
        let sum_a = digit_sum(a.0);
        let sum_b = digit_sum(b.0);
        sum_a.cmp(&sum_b).then(a.1.cmp(&b.1))
    });
    indexed.into_iter().map(|(n, _)| n).collect()
}

fn digit_sum(n: isize) -> usize {
    let abs = n.abs();
    let mut sum = 0;
    let mut num = abs;
    if num == 0 {
        return 0;
    }
    while num > 0 {
        sum += (num % 10) as usize;
        num /= 10;
    }
    sum
}
