/// Write a function to check whether the given number is undulating or not.
fn is_undulating(n: isize) -> bool {
    if n < 0 {
        return false;
    }
    let s = n.to_string();
    let len = s.len();
    if len < 3 {
        return false;
    }
    // An undulating number has the form ababab... where a != b
    // So digits alternate between two values, and those two values are different
    let digits: Vec<char> = s.chars().collect();
    let a = digits[0];
    let b = digits[1];
    if a == b {
        return false;
    }
    for i in 2..len {
        let expected = if i % 2 == 0 { a } else { b };
        if digits[i] != expected {
            return false;
        }
    }
    true
}
