/// In this problem, you will implement a function that takes two vectors of numbers,
/// and determines whether it is possible to perform an exchange of elements
/// between them to make lst1 a vector of only even numbers.
/// There is no limit on the number of exchanged elements between lst1 and lst2.
/// If it is possible to exchange elements between the lst1 and lst2 to make
/// all the elements of lst1 to be even, return "YES".
/// Otherwise, return "NO".
/// For example:
/// >>> exchange(vec![1, 2, 3, 4], vec![1, 2, 3, 4])
/// String::from("YES")
/// >>> exchange(vec![1, 2, 3, 4], vec![1, 5, 3, 4])
/// String::from("NO")
/// It is assumed that the input vectors will be non-empty.
fn exchange(lst1: Vec<isize>, lst2: Vec<isize>) -> String {
    // Count how many odd numbers are in lst1
    let odd_in_lst1: Vec<isize> = lst1.iter().filter(|&&x| x % 2 != 0).cloned().collect();

    // Count how many even numbers are in lst2 (these can be used to replace odd numbers in lst1)
    let even_in_lst2: Vec<isize> = lst2.iter().filter(|&&x| x % 2 == 0).cloned().collect();

    // We need to replace each odd number in lst1 with an even number from lst2
    if odd_in_lst1.len() <= even_in_lst2.len() {
        String::from("YES")
    } else {
        String::from("NO")
    }
}
