        .map(|c| {
            if c.is_ascii_lowercase() {
                let shifted = ((c as u8 - b'a' + 4) % 26) + b'a';
                shifted as char
            } else if c.is_ascii_uppercase() {
                let shifted = ((c as u8 - b'A' + 4) % 26) + b'A';
                shifted as char
            } else {
