/// Write a function to calculate the sum of perrin numbers.
fn cal_sum(n: isize) -> isize {
    if n <= 0 {
        return 0;
    }
    let n = n as usize;
    if n == 0 {
        return 0;
    }
    // Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3) for n>=3
    // Sum of first n+1 Perrin numbers (indices 0 to n)
    if n == 0 {
        return 3;
    }
    if n == 1 {
        return 3 + 0;
    }
    if n == 2 {
        return 3 + 0 + 2;
    }

    let mut p0: isize = 3; // P(0)
    let mut p1: isize = 0; // P(1)
    let mut p2: isize = 2; // P(2)
    let mut sum: isize = p0 + p1 + p2;

    for i in 3..=n {
        let p_next = p2 + p0;
        sum += p_next;
        p0 = p1;
        p1 = p2;
        p2 = p_next;
    }

    sum
}
