    // So the count of polite numbers <= x is x - (floor(log2(x)) + 1).
    // We want the smallest x such that x - (floor(log2(x)) + 1) >= n.

    // Let's binary search for the answer.
    let mut lo: isize = 1;
    let mut hi: isize = 2 * n + 10; // upper bound

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        // Count of powers of 2 <= mid
        let mut pow2_count: isize = 0;
        let mut p: isize = 1;
        while p <= mid {
            pow2_count += 1;
            if mid / 2 < p {
                break;
            }
            p *= 2;
        }
        let polite_count = mid - pow2_count;
        if polite_count < n {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    lo
}
