/// Write a function to find the largest sum of a contiguous vector in the modified vector which is formed by repeating the given vector k times.
fn max_sub_array_sum_repeated(a: Vec<isize>, n: isize, k: isize) -> isize {
    if a.is_empty() {
        return 0;
    }

    let n = n as usize;
    let k = k as usize;

    // Kadane's algorithm for a single array
    let kadane_single = |arr: &[isize]| -> isize {
        let mut max_so_far = arr[0];
        let mut current_max = arr[0];
        for &x in &arr[1..] {
            current_max = std::cmp::max(x, current_max + x);
            max_so_far = std::cmp::max(max_so_far, current_max);
        }
        max_so_far
    };

    // Case 1: k == 1, just run Kadane's on the original array
    if k == 1 {
        return kadane_single(&a);
    }

    // Case 2: k == 2, run Kadane's on a concatenated array of two copies
    if k == 2 {
        let mut doubled = a.clone();
        doubled.extend_from_slice(&a);
        return kadane_single(&doubled);
    }

    // For k >= 2, the maximum subarray sum can be:
    // 1. The maximum subarray sum within a single copy (kadane_single)
    // 2. A subarray that wraps around from the end of one copy to the beginning of another.
    //    This can be computed as: total_sum * (k - 2) + max_suffix_sum + max_prefix_sum
    //    where max_suffix_sum is the maximum suffix sum of the array,
    //    and max_prefix_sum is the maximum prefix sum of the array.

    let total_sum: isize = a.iter().sum();
    let max_single = kadane_single(&a);

    // Compute max prefix sum
    let mut max_prefix = a[0];
    let mut current_prefix = a[0];
    for i in 1..n {
        current_prefix += a[i];
        max_prefix = std::cmp::max(max_prefix, current_prefix);
    }

    // Compute max suffix sum
    let mut max_suffix = a[n - 1];
    let mut current_suffix = a[n - 1];
    for i in (0..n - 1).rev() {
        current_suffix += a[i];
        max_suffix = std::cmp::max(max_suffix, current_suffix);
    }

    // If total_sum > 0, the wrapped sum can benefit from repeating the middle part
    let max_wrapped = if total_sum > 0 {
        total_sum * (k as isize - 2) + max_suffix + max_prefix
    } else {
        max_suffix + max_prefix
    };

    std::cmp::max(max_single, max_wrapped)
}
