/// Write a rsthon function to find the sum of the product of consecutive binomial co-efficients.
fn sum_Of_product(n: isize) -> isize {
    if n < 0 {
        return 0;
    }
    let n = n as usize;
    let mut sum: isize = 0;
    for k in 0..=n {
        let c1 = binomial(n, k);
        let c2 = binomial(n, k + 1);
        sum += c1 * c2;
    }
    sum
}

fn binomial(n: usize, k: usize) -> isize {
    if k > n {
        return 0;
    }
    if k == 0 || k == n {
        return 1;
    }
    let mut result: isize = 1;
    for i in 0..k {
        result = result * (n - i) as isize / (i + 1) as isize;
    }
    result
}
