/// Create a function which takes a string representing a file's name, and returns
/// 'Yes' if the the file's name is valid, and returns 'No' otherwise.
/// A file's name is considered to be valid if and only if all the following conditions 
/// are met:
/// - There should not be more than three digits ('0'-'9') in the file's name.
/// - The file's name contains exactly one dot '.'
/// - The substring before the dot should not be empty, and it starts with a letter from 
/// the latin alphapet ('a'-'z' and 'A'-'Z').
/// - The substring after the dot should be one of these: ['txt', 'exe', 'dll']
/// Examples:
/// >>> file_name_check(String::from("example.txt"))
/// String::from("Yes")
/// >>> file_name_check(String::from("1example.dll"))
/// String::from("No")
fn file_name_check(file_name: String) -> String {
    // Check for exactly one dot
    let dot_count = file_name.chars().filter(|&c| c == '.').count();
    if dot_count != 1 {
        return String::from("No");
    }

    // Split by the dot
    let parts: Vec<&str> = file_name.split('.').collect();
    if parts.len() != 2 {
        return String::from("No");
    }

    let before_dot = parts[0];
    let after_dot = parts[1];

    // Substring before the dot should not be empty
    if before_dot.is_empty() {
        return String::from("No");
    }

    // Substring before the dot should start with a letter
    let first_char = before_dot.chars().next().unwrap();
    if !first_char.is_ascii_alphabetic() {
        return String::from("No");
    }

    // Substring after the dot should be one of ['txt', 'exe', 'dll']
    if after_dot != "txt" && after_dot != "exe" && after_dot != "dll" {
