/// Write a rsthon function to remove first and last occurrence of a given character from the string.
fn remove_Occ(s: String, ch: String) -> String {
    let ch = ch.chars().next().unwrap();
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();

    // Find first occurrence
    let first = chars.iter().position(|&c| c == ch);
    // Find last occurrence
    let last = chars.iter().rposition(|&c| c == ch);

    match (first, last) {
        (Some(f), Some(l)) if f != l => {
            let mut result = String::new();
            for (i, &c) in chars.iter().enumerate() {
                if i != f && i != l {
                    result.push(c);
                }
            }
            result
        }
        (Some(f), Some(l)) if f == l => {
            // Only one occurrence, remove it
            let mut result = String::new();
            for (i, &c) in chars.iter().enumerate() {
                if i != f {
                    result.push(c);
                }
            }
            result
