    }

    let mut max_so_far = arr[0];
    let mut min_so_far = arr[0];
    let mut result = arr[0];

    for i in 1..arr.len() {
        let current = arr[i];
        if current < 0 {
            std::mem::swap(&mut max_so_far, &mut min_so_far);
        }
        max_so_far = std::cmp::max(current, max_so_far * current);
