/// Write a rsthon function to find element at a given index after number of rotations.
fn find_Element(arr: Vec<isize>, ranges: Vec<Vec<isize>>, rotations: isize, index: isize) -> isize {
    let n = arr.len() as isize;
    if n == 0 {
        return 0;
    }
    // Normalize rotations to be within [0, n)
    let effective_rotations = ((rotations % n) + n) % n;
    // After rotating right by effective_rotations, the element at original index i moves to (i + effective_rotations) % n
    // So the element at position `index` after rotation comes from original index (index - effective_rotations) mod n
    let original_index = ((index - effective_rotations) % n + n) % n;
    arr[original_index as usize]
}
