/// Return vector of prime factors of given integer in the order from smallest to largest.
/// Each of the factors should be vectored number of times corresponding to how many times it appeares in factorization.
/// Input number should be equal to the product of all factors
/// >>> factorize(8)
/// vec![2, 2, 2]
/// >>> factorize(25)
/// vec![5, 5]
/// >>> factorize(70)
/// vec![2, 5, 7]
fn factorize(n: isize) -> Vec<isize> {
    if n <= 1 {
        return vec![];
    }

    let mut factors = Vec::new();
    let mut num = n;

    // Handle factor 2
    while num % 2 == 0 {
        factors.push(2);
        num /= 2;
    }

    // Handle odd factors from 3 upwards
    let mut divisor = 3;
    while divisor * divisor <= num {
        while num % divisor == 0 {
            factors.push(divisor);
            num /= divisor;
        }
        divisor += 2;
    }

    // If num is still greater than 1, then it's a prime factor
    if num > 1 {
        factors.push(num);
    }

    factors
}
