/// Write a rsthon function to find the surface area of a square rsramid with a given base edge and height.
fn surface_Area(b: isize, s: isize) -> isize {
    // Surface area of a square pyramid = base area + lateral area
    // Base area = b^2
    // Lateral area = 4 * (1/2 * b * slant_height) = 2 * b * slant_height
    // Slant height = sqrt((b/2)^2 + s^2)
    // Since we're working with isize, we need to handle this carefully.
    // For integer arithmetic, we'll compute using f64 and round.

    let b_f64 = b as f64;
    let s_f64 = s as f64;

    let base_area = b_f64 * b_f64;

    // Slant height calculation
    let half_b = b_f64 / 2.0;
    let slant_height = (half_b * half_b + s_f64 * s_f64).sqrt();

    let lateral_area = 2.0 * b_f64 * slant_height;

    let total_area = base_area + lateral_area;

    total_area.round() as isize
}
