/// Examples:
/// >>> decimal_to_binary(15)
/// String::from("db1111db")
/// >>> decimal_to_binary(32)
/// String::from("db100000db")
fn decimal_to_binary(decimal: isize) -> String {
    if decimal == 0 {
        return String::from("db0db");
    }

    let mut n = decimal.unsigned_abs();
    let mut binary_digits = Vec::new();

    while n > 0 {
        binary_digits.push(if n % 2 == 0 { '0' } else { '1' });
        n /= 2;
    }

    binary_digits.reverse();
    let binary_str: String = binary_digits.into_iter().collect();

    format!("db{}db", binary_str)
}
