/// Write a function to find the maximum product formed by multiplying numbers of an increasing subsequence of that vector.
fn max_product(arr: Vec<isize>) -> isize {
    if arr.is_empty() {
        return 0;
    }

    let n = arr.len();
    // dp[i] stores the maximum product of an increasing subsequence ending at index i
    let mut dp: Vec<isize> = vec![1; n];
    let mut max_prod: isize = arr[0];

    for i in 0..n {
        dp[i] = arr[i];
        for j in 0..i {
            if arr[j] < arr[i] {
                let candidate = dp[j] * arr[i];
                if candidate > dp[i] {
                    dp[i] = candidate;
                }
            }
        }
        if dp[i] > max_prod {
            max_prod = dp[i];
        }
    }

    max_prod
}
