fn get_closest_vowel(word: String) -> String {
    let chars: Vec<char> = word.chars().collect();
    let len = chars.len();

    if len < 3 {
        return String::new();
    }

    let is_vowel = |c: char| -> bool {
        matches!(c.to_ascii_lowercase(), 'a' | 'e' | 'i' | 'o' | 'u')
    };

    let is_consonant = |c: char| -> bool {
        c.is_ascii_alphabetic() && !is_vowel(c)
    };

    // We need to find the closest vowel from the right side that stands between two consonants.
    // "from the right side" means we start checking from the rightmost possible position.
    // A vowel at index i is between two consonants if chars[i-1] is a consonant and chars[i+1] is a consonant.
    // We want the rightmost such vowel.

    // Vowels at the beginning (index 0) and ending (index len-1) don't count.
    // So we check indices from len-2 down to 1.

    for i in (1..len - 1).rev() {
        if is_vowel(chars[i]) && is_consonant(chars[i - 1]) && is_consonant(chars[i + 1]) {
            return chars[i].to_string();
        }
    }

    String::new()
}
