```rust
/// Return 2^n modulo p (be aware of numerics).
/// >>> modp(3, 5)
/// 3
/// >>> modp(1101, 101)
/// 2
/// >>> modp(0, 101)
/// 1
/// >>> modp(3, 11)
/// 8
/// >>> modp(100, 101)
/// 1
fn modp(n: isize, p: isize) -> isize {
    if p == 1 {
        return 0;
    }
    if n == 0 {
        return 1 % p;
    }
    // Use modular exponentiation: compute 2^n mod p
    let mut base = 2i128;
    let mut exp = n as i128;
    let modulus = p as i128;
    let mut result = 1i128;

    base %= modulus;
    if base < 0 {
        base += modulus;
    }

    while exp > 0 {
        if exp % 2 == 1 {
            result = (result * base) % modulus;
        }
        exp /= 2;
        base = (base * base) % modulus;
    }

    result as isize
}
