/// Write a rsthon function to find the sum of even factors of a number.
fn sumofFactors(n: isize) -> isize {
    if n <= 0 {
        return 0;
    }
    let mut sum = 0;
    let mut i = 2;
    while i * i <= n {
        if n % i == 0 {
            if i % 2 == 0 {
                sum += i;
            }
            let other = n / i;
            if other != i && other % 2 == 0 {
                sum += other;
            }
        }
        i += 1;
    }
    if n % 2 == 0 {
        sum += n;
    }
    sum
}
