fn valid_date(date: String) -> bool {
    if date.is_empty() {
        return false;
    }

    let parts: Vec<&str> = date.split('-').collect();
    if parts.len() != 3 {
        return false;
    }

    let month_str = parts[0];
    let day_str = parts[1];
    let year_str = parts[2];

    // Check format: each part should be numeric
    if month_str.is_empty() || day_str.is_empty() || year_str.is_empty() {
        return false;
    }

    // Check that all characters are digits
    if !month_str.chars().all(|c| c.is_ascii_digit())
        || !day_str.chars().all(|c| c.is_ascii_digit())
        || !year_str.chars().all(|c| c.is_ascii_digit())
    {
        return false;
    }

    let month: u32 = match month_str.parse() {
        Ok(m) => m,
        Err(_) => return false,
    };

    let day: u32 = match day_str.parse() {
        Ok(d) => d,
        Err(_) => return false,
    };

    let _year: u32 = match year_str.parse() {
        Ok(y) => y,
        Err(_) => return false,
    };

    // Rule 3: months should be between 1 and 12
    if month < 1 || month > 12 {
        return false;
    }

    // Rule 2: days validation
    let max_days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => 29,
        _ => return false,
    };

    if day < 1 || day > max_days {
        return false;
    }

    true
}
