/// Write a rsthon function to find nth bell number.
fn bell_Number(n: isize) -> isize {
    if n < 0 {
        return 0;
    }
    let n = n as usize;
    // Bell numbers can be computed using the Bell triangle or using the recurrence:
    // B(n+1) = sum_{k=0}^{n} C(n,k) * B(k)
    // We'll use dynamic programming with the recurrence.

    let mut bell = vec![0isize; n + 1];
    bell[0] = 1;

    for i in 1..=n {
        let mut sum = 0isize;
        for k in 0..i {
            // C(i-1, k) * bell[k]
            sum += combinations(i - 1, k) * bell[k];
        }
        bell[i] = sum;
    }

    bell[n]
}

/// Compute binomial coefficient C(n, k)
fn combinations(n: usize, k: usize) -> isize {
    if k > n {
        return 0;
    }
    if k == 0 || k == n {
        return 1;
    }
    let mut result = 1isize;
    for i in 0..k {
        result = result * (n - i) as isize / (i + 1) as isize;
    }
    result
}
